    def dotted(self):

        if self._dotted is None:
            output = []

            part = 0
            for byte in self.contents:
                part = part * 128
                part += byte & 127
                if byte & 0x80 == 0:
                    if len(output) == 0:
                        if part >= 80:
                            output.append(str(2))
                            output.append(str(part - 80))
                        elif part >= 40:
                            output.append(str(1))
                            output.append(str(part - 40))
                        else:
                            output.append(str(0))
                            output.append(str(part))
                    else:
                        output.append(str(part))
                    part = 0

            self._dotted = '.'.join(output)
        return self._dotted

    @property
    def native(self):

        if self.contents is None:
            return None

        if self._native is None:
            self._native = self.dotted
        if self._map is not None and self._native in self._map:
            self._native = self._map[self._native]
        return self._native


